import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    degrees = []
    xor_sums = []

    for i in range(n):
        d = int(next(iterator))
        s = int(next(iterator))
        degrees.append(d)
        xor_sums.append(s)

    q = deque()
    for i in range(n):
        if degrees[i] == 1:
            q.append(i)

    edges = []

    while q:
        u = q.popleft()
        if degrees[u] == 0:
            continue

        v = xor_sums[u]

        if degrees[v] > 0:
            edges.append((u, v))

            degrees[u] -= 1
            degrees[v] -= 1

            xor_sums[v] ^= u

            if degrees[v] == 1:
                q.append(v)

    print(len(edges))
    for a, b in edges:
        print(f"{a} {b}")

if __name__ == "__main__":
    main()
